import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../services/api';

function Dashboard() {
    const [user, setUser] = useState(null);
    const [alimentos, setAlimentos] = useState([]);
    const navigate = useNavigate();

    useEffect(() => {
        const loggedUser = JSON.parse(localStorage.getItem('user'));
        if (!loggedUser) {
            navigate('/');
        } else {
            setUser(loggedUser);
            carregarAlimentos();
        }
    }, []);

    const carregarAlimentos = async () => {
        try {
            const response = await api.get('/alimento/disponiveis'); 
            setAlimentos(response.data);
        } catch (err) {
            console.error("Erro ao carregar alimentos", err);
        }
    };

    const handleLogout = () => {
        localStorage.removeItem('user');
        navigate('/');
    };

    if (!user) return null;

    return (
        <div style={{ padding: '20px' }}>
            <header style={{ display: 'flex', justifyContent: 'space-between' }}>
                <h1>Food Care - Painel {user.tipoUsuario}</h1>
                <button onClick={handleLogout}>Sair</button>
            </header>

            <hr />

            {user.tipoUsuario === 'DOADOR' ? (
                <div>
                    <h3>Meus Alimentos para Doação</h3>
                    <button style={{ backgroundColor: 'green', color: 'white' }}>+ Cadastrar Novo Alimento</button>
                </div>
            ) : (
                <div>
                    <h3>Alimentos Disponíveis</h3>
                    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '10px' }}>
                        {alimentos.map(alimento => (
                            <div key={alimento.id} style={{ border: '1px solid #ccc', padding: '10px', borderRadius: '8px' }}>
                                <h4>{alimento.nome}</h4>
                                <p>Validade: {alimento.dataValidade}</p>
                                <p>Qtd Disponível: {alimento.quantidadeTotal - alimento.quantidadeReservada}</p>
                                <button onClick={() => alert('Solicitação em breve!')}>Solicitar</button>
                            </div>
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
}

export default Dashboard;
